using System;using System.Collections;using System.Collections.Generic;using System.Reflection;using System.IO;using UnityEngine;
public sealed class DigitalKingdomPresentationValidation:MonoBehaviour {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;readonly List<string> results=new List<string>();public bool Done{get;private set;}
 void Check(bool ok,string text){results.Add((ok?"PASS ":"FAIL ")+text);}
 public void Run(){StartCoroutine(Checks());}
 IEnumerator Checks(){var a=UnityEngine.Object.FindFirstObjectByType<DungeonAudio>();var original=a.settings;var temp=Instantiate(original);var one=AudioClip.Create("Playlist fixture A",6615,1,22050,false);var two=AudioClip.Create("Playlist fixture B",6615,1,22050,false);var three=AudioClip.Create("Playlist fixture C",6615,1,22050,false);var t=typeof(DungeonAudio);var music=(AudioSource)t.GetField("musicSource",F).GetValue(a);var owner=UnityEngine.Object.FindFirstObjectByType<DungeonPrototype>();bool enabled=owner.enabled;owner.enabled=false;
 try{a.settings=temp;temp.explorationPlaylist=new AudioClip[0];temp.normalCombatPlaylist=new AudioClip[0];t.GetField("baseContextKnown",F).SetValue(a,false);DungeonAudio.SetCombat(false);Check(music.clip==original.dungeonMusic,"Empty playlist preserves legacy exploration track");temp.explorationPlaylist=new[]{one,null,one,two,three};var tracks=(List<AudioClip>)t.GetMethod("Tracks",F).Invoke(a,new object[]{false});Check(tracks.Count==3,"Playlist ignores null and duplicate references");
 temp.shufflePlaylist=false;t.GetField("baseContextKnown",F).SetValue(a,false);t.GetField("lastExploration",F).SetValue(a,null);DungeonAudio.SetCombat(false);Check(music.clip==one,"Sequential playlist starts at first track");yield return new WaitForSecondsRealtime(.12f);int sample=music.timeSamples;DungeonAudio.SetCombat(false);yield return new WaitForSecondsRealtime(.03f);Check(music.clip==one&&music.timeSamples>sample,"Per-frame exploration updates do not restart music");yield return new WaitForSecondsRealtime(.4f);Check(music.clip==two||music.clip==three,"Playlist advances automatically when a track finishes");
 temp.shufflePlaylist=true;bool varied=true;AudioClip previous=null;for(int i=0;i<30;i++){t.GetField("baseContextKnown",F).SetValue(a,false);var next=(AudioClip)t.GetMethod("BaseTrack",F).Invoke(a,new object[]{false});varied&=next!=null&&next!=previous;previous=next;}Check(varied,"Shuffle avoids immediate repeats across 30 selections");
 temp.normalCombatPlaylist=new[]{two};t.GetField("baseContextKnown",F).SetValue(a,false);DungeonAudio.SetCombat(true);yield return new WaitForSecondsRealtime(.65f);Check(music.clip==two&&music.loop,"Normal combat uses its independent playlist");yield return new WaitForSecondsRealtime(.08f);sample=music.timeSamples;DungeonAudio.SetCombat(true);Check(music.clip==two&&music.timeSamples==sample&&music.isPlaying,"Repeated combat updates keep track position");
 var landing=MakongSpecialSettings.Current.landingSound;Check(landing!=null&&landing.length>.5f&&landing.length<1,"Makong heavy landing clip assigned");float[] samples=new float[landing.samples];landing.GetData(samples,0);float peak=0;foreach(float x in samples)peak=Mathf.Max(peak,Mathf.Abs(x));Check(peak>.7f&&peak<1,"Landing impact has audible level without sample clipping");Check(a.GetComponents<AudioSource>().Length==2,"Playlists reuse existing music and SFX sources");
 }finally{a.settings=original;t.GetField("baseContextKnown",F).SetValue(a,false);DungeonAudio.SetCombat(false);owner.enabled=enabled;Destroy(temp);Destroy(one);Destroy(two);Destroy(three);Done=true;File.WriteAllLines("Tests/DigitalKingdomPresentationResults.txt",results);Debug.Log("City presentation tests\n"+string.Join("\n",results.ToArray()));}
 }
}
